#!/usr/bin/env node
/**
 * The Annotated World: source → quote/context/annotation timeline validator.
 * No media is generated by this script. A passed structural check is NOT publish approval.
 */
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const FMT = 'annotated-quote-alternation/v1';
const [command, requestedPath, ...flags] = process.argv.slice(2);
const fail = (msg) => { console.error(msg); process.exitCode = 1; };
const nonempty = x => typeof x === 'string' && !!x.trim();
const normEN = x => String(x ?? '').replace(/\s+/g,' ').trim();
const normJA = x => String(x ?? '').replace(/\s+/g,'').trim();
const within = (v,container) => nonempty(v) && (String(container).includes(v) || String(container).toLowerCase().includes(v.toLowerCase()));
const read = file => JSON.parse(fs.readFileSync(file,'utf8'));
const attr = (obj,key) => obj && obj[key];

function validate(b, {media=false,publish=false,base=process.cwd()}={}) {
  const errors=[], warnings=[];
  const err=(p,m)=>errors.push(p+': '+m);
  const warn=(p,m)=>warnings.push(p+': '+m);
  if(b.format!==FMT) err('format','must equal '+FMT);
  if(!nonempty(b.title)) err('title','required');
  if(!nonempty(attr(b.speaker,'name'))) err('speaker.name','required: who is being quoted?');
  if(!nonempty(attr(b.speaker,'voiceId'))) err('speaker.voiceId','required');
  if(!nonempty(attr(b.speaker,'voiceDisclosure'))) err('speaker.voiceDisclosure','synthetic vs authentic audio disclosure required');
  if(!nonempty(attr(b.speaker,'portrait'))) err('speaker.portrait','required');
  if(!nonempty(attr(b.editor,'name'))) err('editor.name','required');
  if(!nonempty(attr(b.editor,'voiceId'))) err('editor.voiceId','required');
  if(attr(b.speaker,'voiceId')===attr(b.editor,'voiceId')) err('voices','speaker and editor must have distinct voice identities');
  if(!nonempty(attr(b.source,'url'))) err('source.url','required');
  if(!nonempty(attr(b.source,'document'))) err('source.document','required');
  if(!nonempty(attr(b.source,'eventContext'))) err('source.eventContext','place and setting required for early source introduction');
  if(!nonempty(attr(b.music,'path'))) err('music.path','required');
  if(!nonempty(attr(b.music,'credit'))) err('music.credit','required; original music must still name its creation/rights');
  if(!Array.isArray(b.segments)||b.segments.length<5) err('segments','need at least quote → context → quote → annotation → quote');
  const seq=Array.isArray(b.segments)?b.segments:[];
  const roles=seq.map(s=>s.role);
  if(roles[0]!=='QUOTE'||roles[1]!=='CONTEXT'||roles[2]!=='QUOTE')err('sequence','start QUOTE (hook) → CONTEXT (source introduction) → QUOTE');
  if(roles.at(-1)!=='QUOTE')err('sequence','the final scene should return to the original speaker');
  if(roles.filter(r=>r==='CONTEXT').length!==1)err('sequence','exactly one CONTEXT immediately after the hook');
  if(!roles.includes('ANNOTATION'))err('sequence','at least one substantive editorial ANNOTATION required');
  const ids=new Set();
  seq.forEach((s,i)=>{
    const p='segments['+i+']';
    if(!['QUOTE','CONTEXT','ANNOTATION'].includes(s.role))err(p+'.role','unrecognized');
    if(!nonempty(s.id)||ids.has(s.id))err(p+'.id','unique nonempty id required');
    ids.add(s.id);
    if(!nonempty(s.asset))err(p+'.asset','required source-related still/footage path');
    if(!nonempty(s.audio))err(p+'.audio','required audio in the expected voice (no implicit fallback)');
    if(s.voiceId && s.voiceId!== (s.role==='QUOTE'?b.speaker?.voiceId:b.editor?.voiceId))
      err(p+'.voiceId','cannot change narrator within a role');
    if(!Array.isArray(s.cues)||!s.cues.length)err(p+'.cues','speech-synchronous caption units required');
    const cues=Array.isArray(s.cues)?s.cues:[];
    if(s.role==='QUOTE'){
      if(!nonempty(s.en)||!nonempty(s.ja))err(p,'original English plus Japanese translation required');
      if(!nonempty(s.sourceTime))err(p+'.sourceTime','source location/time required');
      if(s.isVerbatim!==true)err(p+'.isVerbatim','must assert checked verbatim quote; paraphrases cannot be presented as quotations');
      if(normEN(cues.map(c=>c.en).join(' '))!==normEN(s.en))err(p+'.cues.en','cue texts must reproduce the entire English quotation without omission');
      if(normJA(cues.map(c=>c.ja).join(''))!==normJA(s.ja))err(p+'.cues.ja','cue texts must reproduce Japanese translation without omission');
      cues.forEach((c,j)=>{
        if(!nonempty(c.en)||!nonempty(c.ja))err(p+'.cues['+j+']','both languages required for QUOTE');
        if(c.hiEN && !within(c.hiEN,c.en))err(p+'.cues['+j+'].hiEN','highlight not contained in English cue');
        if(c.hiJA && !within(c.hiJA,c.ja))err(p+'.cues['+j+'].hiJA','highlight not contained in Japanese cue');
        if(!!c.hiEN!==!!c.hiJA)err(p+'.cues['+j+']','English/Japanese highlight must be paired');
        if((c.en||'').length>130)warn(p+'.cues['+j+']','long cue: likely too many subtitle lines at smartphone size');
      });
    } else {
      if(nonempty(s.en)||cues.some(c=>nonempty(c.en)))err(p,'editorial voice must not be displayed as spoken source English');
      if(!nonempty(s.ja))err(p+'.ja','substantive contextual spoken text required');
      if(normJA(cues.map(c=>c.ja).join(''))!==normJA(s.ja))err(p+'.cues.ja','cue text must reproduce spoken note completely');
      if(!nonempty(s.noteTitle)||!nonempty(s.evidence))err(p,'noteTitle and evidence required, not just a decorative label');
      if(s.ja.trim().length<25)err(p+'.ja','substantive explanation required, not just a term label');
      if(i===1&&s.role!=='CONTEXT')err(p,'intro must be context');
      if(s.role==='ANNOTATION' && (roles[i-1]!=='QUOTE'||roles[i+1]!=='QUOTE'))err(p,'annotation must sit between quotation segments');
      if(s.role==='CONTEXT'&&i!==1)err(p,'context belongs immediately after hook');
      cues.forEach((c,j)=>{if(!nonempty(c.ja))err(p+'.cues['+j+']','Japanese cue missing');});
    }
    if(media){
      for(const [field,f] of [['audio',s.audio],['asset',s.asset]]){
        const file=path.resolve(base,f||'');if(!fs.existsSync(file))err(p+'.'+field,'media file missing: '+file);
      }
    }
  });
  if(media){
    for(const [p,f] of [['speaker.portrait',b.speaker?.portrait],['music.path',b.music?.path]]){
      const file=path.resolve(base,f||'');if(!fs.existsSync(file))err(p,'media file missing: '+file);
    }
  }
  if(!b.source?.originalAudioChecked)warn('source.originalAudioChecked','original recording not verified, do not imply original voice');
  if(publish){
    if(b.source?.rightsReviewed!==true)err('source.rightsReviewed','publication requires rights assessment');
    if(b.source?.originalAudioChecked!==true)err('source.originalAudioChecked','source recording/transcript consistency not confirmed');
    if(b.music?.rightsReviewed!==true)err('music.rightsReviewed','recording/sample/soundfont rights not reviewed');
    if(b.publication?.approved!==true)err('publication.approved','explicit human publication authorization required');
    if(!Array.isArray(b.assetCredits)||!b.assetCredits.length)err('assetCredits','credit ledger required');
  }
  return {ok:!errors.length,errors,warnings,segments:seq.length,quotes:roles.filter(x=>x==='QUOTE').length,notes:roles.filter(x=>x!=='QUOTE').length};
}
function usage(){
 console.log('Usage:\n  npm run short:init -- <slug>\n  npm run short:check -- <brief.json> [--media] [--publish]\n  npm run short:plan -- <brief.json> [--output <cutlist.json>]');
}
if(command==='init'){
  if(!/^[a-z0-9][a-z0-9-]{1,65}$/.test(requestedPath||'')){fail('slug: use lower-case letters, numbers, and hyphens');}
  else {
    const dir=path.join(ROOT,'productions',requestedPath);
    if(fs.existsSync(dir))fail('Will not overwrite existing production: '+dir);
    else {
      fs.mkdirSync(dir,{recursive:true});
      const example=read(path.join(ROOT,'templates','annotated-short','brief.example.json'));
      example.title='';example.source.url='';example.source.document='';example.source.eventContext='';
      example.speaker.name='';example.speaker.portrait='assets/speaker.jpg';
      for(const s of example.segments){s.en='';s.ja='';s.audio='audio/'+s.id+'.mp3';s.asset='assets/'+s.id+'.jpg';s.cues=[];if(s.role==='QUOTE')s.isVerbatim=false;}
      fs.writeFileSync(path.join(dir,'brief.json'),JSON.stringify(example,null,2)+'\n');
      for(const folder of ['assets','audio'])fs.mkdirSync(path.join(dir,folder),{recursive:true});
      console.log('Created '+path.relative(ROOT,dir)+'/brief.json (intentionally incomplete; fill real-source data).');
    }
  }
} else if(command==='validate'||command==='plan'){
  if(!requestedPath){usage();fail('missing brief path');}
  else{
    try{
      const full=path.resolve(requestedPath);const b=read(full);
      const result=validate(b,{media:flags.includes('--media'),publish:flags.includes('--publish'),base:path.dirname(full)});
      for(const w of result.warnings)console.warn('WARN '+w);
      for(const e of result.errors)console.error('ERROR '+e);
      if(!result.ok)process.exitCode=1;
      else if(command==='validate')console.log('PASS '+JSON.stringify({segments:result.segments,quotes:result.quotes,contextAndNotes:result.notes}));
      else {
        const cutlist=b.segments.map((s,i)=>({
          order:i+1,role:s.role,id:s.id,speaker:s.role==='QUOTE'?b.speaker.name:b.editor.name,
          voiceId:s.role==='QUOTE'?b.speaker.voiceId:b.editor.voiceId,
          audio:s.audio,asset:s.asset,subtitleMode:s.role==='QUOTE'?'EN+JA (source)':'JA only (editor)',
          captionUnits:s.cues.length,sourceTime:s.sourceTime??null,evidence:s.evidence??null
        }));
        const outAt=flags.indexOf('--output');const resultPath=outAt>=0?flags[outAt+1]:null;
        if(resultPath)fs.writeFileSync(resultPath,JSON.stringify(cutlist,null,2)+'\n');
        else console.log(JSON.stringify(cutlist,null,2));
      }
    }catch(err){fail('Unable to process brief: '+err.message);}
  }
}else {usage();fail('unknown command');}
